    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint timestamp) public payable {
        require(amount == 10 ether, "exact amount required");
        require(timestamp > c.pastBlockTime(), "timestamp must increase");
        require(address(this).balance >= amount, "insufficient test balance");

        uint pastBlockTimeBefore = c.pastBlockTime();
        uint balanceBefore = address(c).balance;
        uint balanceOfTestBefore = address(this).balance;

        (bool success, ) = address(c).call{value: amount}("");

        if (success) {
            assert(c.pastBlockTime() == block.timestamp);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance == balanceOfTestBefore + balanceBefore);
            } else {
                assert(address(c).balance == balanceBefore + amount);
                assert(address(this).balance == balanceOfTestBefore - amount);
            }
        } else {
            assert(c.pastBlockTime() == pastBlockTimeBefore);
            assert(address(c).balance == balanceBefore);
            assert(address(this).balance == balanceOfTestBefore);
        }
    }

    receive() external payable {}
}

