contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 firstValue, uint256 secondValue) public payable {
        require(firstValue == 10 ether, "first value must be 10 ether");
        require(secondValue == 10 ether, "second value must be 10 ether");

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBalance = address(this).balance;
        require(beforeBalance >= firstValue + secondValue, "insufficient balance");

        bool firstReverted;
        try c.call{value: firstValue}("") {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 midTime = c.pastBlockTime();
        uint256 midBalance = address(this).balance;

        if (!firstReverted && midTime != beforeTime) {
            assert(midTime == block.timestamp);
        }

        if (!firstReverted) {
            require(midBalance >= secondValue, "insufficient balance after first call");

            bool secondReverted;
