contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newTime, uint256 amount) public payable {
        // Precondition: amount must be exactly 10 ether, and the new timestamp must be strictly greater than the current stored pastBlockTime
        require(amount == 10 ether, "amount must be 10 ether");
        require(newTime > c.pastBlockTime(), "new time must be greater than pastBlockTime");
        require(address(this).balance >= amount, "insufficient balance");

        // Record the previous balance of the test contract before the call
        uint256 prevSelfBalance = address(this).balance;

        bool reverted;
        try c.call{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The call must not revert
        assert(!reverted);

        // The stored pastBlockTime must equal the current block timestamp, which after a transaction
        // equals newTime (since the call is made within this transaction and no other timestamp-changing
        // operation occurs)
        assert(c.pastBlockTime() == block.timestamp);

        // If the current block number is divisible by 15, the entire balance (including the 10 ether sent)
        // is transferred to the caller (this test contract). The test contract receives the amount back,
        // so its balance should be prevSelfBalance + 10 ether in that case.
        // Otherwise, the test contract's balance is prevSelfBalance - 10 ether.
        if (block.number % 15 == 0) {
            assert(address(this).balance == prevSelfBalance + amount);
        } else {
            assert(address(this).balance == prevSelfBalance - amount);
        }
    }

    receive() external payable {}
}

