    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint amount = 10 ether;

        require(address(this).balance >= amount, "not enough balance for seed");
        c.call{value: amount}("");

        uint beforeBalance = address(c).balance;
        uint beforePast = c.pastBlockTime();

        require(address(this).balance >= amount, "not enough balance for reverting call");
        bool reverted;
        (bool success, ) = address(c).call{value: amount}("");
        reverted = !success;

        assert(reverted && address(c).balance == beforeBalance && c.pastBlockTime() == beforePast);
    }

    receive() external payable {}
}

