contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint laterOffset) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        bool revertFirst;
        try c.fallback{value: amount}() {
            revertFirst = false;
        } catch {
            revertFirst = true;
        }

        if (revertFirst) {
            assert(amount != 10 ether || block.timestamp <= c.pastBlockTime());
            return;
        }

        uint firstRecorded = c.pastBlockTime();
        uint secondAmount = 10 ether;
        uint secondLaterOffset = laterOffset;

        if (address(this).balance < secondAmount) {
            secondAmount = address(this).balance;
        }

        if (secondAmount == 10 ether && block.timestamp > c.pastBlockTime()) {
            c.fallback{value: secondAmount}();
            assert(c.pastBlockTime() >= firstRecorded && c.pastBlockTime() == block.timestamp);
        } else {
            assert(c.pastBlockTime() == firstRecorded);
        }
    }

    receive() external payable {}
}

