contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 ts) public payable {
        require(address(this).balance >= 10 ether, "not enough balance");

        uint256 beforePastBlockTime = c.pastBlockTime();
        require(beforePastBlockTime == 0, "pastBlockTime must start at 0 for this test");

        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;
        bool reverted;

        // The fallback requires a value of exactly 10 ether and a timestamp strictly
        // greater than pastBlockTime (which started at 0), so ts > 0 is needed.
        require(ts > 0, "timestamp must be greater than 0");

        // Use the provided timestamp so the execution takes the successful path.
        try {
            c.call{value: 10 ether}(abi.encodePacked(bytes4(keccak256("fallback()"))));
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPastBlockTime = c.pastBlockTime();

        // General rule: a successful fallback call with value 10 ether and timestamp ts > 0
        // updates c.pastBlockTime to ts and moves the 10 ether into c, unless the
        // block number condition triggers a transfer of the entire balance back to the caller.
        if (!reverted) {
            assert(afterPastBlockTime == ts);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance == thisBalanceBefore);
            } else {
                assert(address(c).balance == cBalanceBefore + 10 ether);
                assert(address(this).balance == thisBalanceBefore - 10 ether);
            }
        } else {
            assert(afterPastBlockTime == beforePastBlockTime);
            assert(address(c).balance == cBalanceBefore);
            assert(address(this).balance == thisBalanceBefore);
        }
    }

    receive() external payable {}
}

