    }

    function run(uint amount, uint timestamp) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Setup: make one successful call so pastBlockTime is nonzero and later than timestamp.
        c.fallback{value: amount}();
        uint firstPastBlockTime = c.pastBlockTime();

        // Read the pre-state for the deciding call.
        uint beforeBalanceC = address(c).balance;
        uint beforePastBlockTime = c.pastBlockTime();

        // Make the deciding call. It may revert only if block.timestamp <= beforePastBlockTime.
        bool reverted = false;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint afterPastBlockTime = c.pastBlockTime();
            uint afterBalanceC = address(c).balance;

            // General rule: a successful call moves pastBlockTime strictly forward and, if
            // block.number % 15 == 0, transfers the whole prior contract balance to the caller.
            if (block.number % 15 == 0) {
                assert(afterBalanceC == 0 && afterPastBlockTime > beforePastBlockTime);
            } else {
                assert(afterBalanceC == beforeBalanceC + amount && afterPastBlockTime > beforePastBlockTime);
            }
        } else {
            // A revert must mean the timestamp guard failed.
            assert(block.timestamp <= beforePastBlockTime);
        }
    }

    receive() external payable {}
}

