                    afterPastBlockTime == block.timestamp
                    && (
                        (block.number % 15 == 0 && thisAfter == thisBefore + beforeBalanceC + amount && afterBalanceC == 0)
                        || (block.number % 15 != 0 && thisAfter == thisBefore - amount && afterBalanceC == beforeBalanceC + amount)
