    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint prevTime = c.pastBlockTime();

        bool success;
        try c.call{value: amount}("") {
            success = true;
        } catch {
            success = false;
