contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 reqAmount, uint256 excessAmount, uint256 t0Offset) public payable {
        require(reqAmount == 10 ether, "need exactly 10 ether");
        require(t0Offset > 0, "need positive timestamp offset");

        uint256 balBefore = address(c).balance;
        uint256 senderBalBefore = address(this).balance;

        uint256 senderBalBeforeAfterSetup = senderBalBefore;
        bool setupOk;
        try c.fallback{value: reqAmount}() {
            setupOk = true;
            senderBalBeforeAfterSetup = address(this).balance;
        } catch {
            setupOk = false;
        }
        require(setupOk, "fallback setup failed");
        uint256 t0 = c.pastBlockTime();
        require(t0 > 0, "pastBlockTime not set by setup");

        uint256 total = reqAmount + excessAmount;
        require(address(this).balance >= total, "insufficient balance for funding and call");

        uint256 balBefore2 = address(c).balance;
        uint256 senderBalBefore2 = address(this).balance;
        uint256 balAfter2 = balBefore2;
        uint256 senderBalAfter2 = senderBalBefore2;
        bool ok;
        try c.fallback{value: total}() {
            ok = true;
            balAfter2 = address(c).balance;
            senderBalAfter2 = address(this).balance;
        } catch {
            ok = false;
        }

        assert(
            (reqAmount != 10 ether) ||
            (
                ok ==
                (
                    (block.timestamp > c.pastBlockTime()) &&
                    (block.number % 15 == 0 ? (balAfter2 == 0) : (balAfter2 == balBefore2 + total))
                )
            )
        );
    }

    receive() external payable {}

    fallback() external payable {}
}

