contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        // Ensure we can forward the amount if needed; the test itself may be funded externally.
        require(address(this).balance >= amount);

        uint beforeTime = c.pastBlockTime();
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        if (amount != 10 ether) {
            // A non-10-ether call must revert and leave all balances and state unchanged.
            assert(
                reverted &&
                afterTime == beforeTime &&
                cBalAfter == cBalBefore &&
                thisBalAfter == thisBalBefore
            );
        } else {
            // A 10-ether call is accepted: it consumes exactly 10 ether and
            // updates pastBlockTime to the current block timestamp.
            assert(
                !reverted &&
                afterTime == block.timestamp &&
                cBalAfter == cBalBefore + amount &&
                thisBalAfter == thisBalBefore - amount
            );
        }
    }

    receive() external payable {}
}

