contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 setupTime) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");

        // Ensure the test contract has enough Ether to fund the call.
        require(address(this).balance >= amount, "insufficient balance");

        // Setup: make the first successful call at a chosen timestamp.
        // The compiler treats block.timestamp as current time; to make the
        // precondition deterministic, we instead require that the current
        // timestamp is already greater than pastBlockTime (initially 0).
        require(block.timestamp > c.pastBlockTime(), "timestamp must increase");

        uint256 balanceBefore = address(c).balance;

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // A successful call updates the stored timestamp to the call time
            // and sends the entire contract balance to msg.sender only when
            // block.number is divisible by 15.
            assert(c.pastBlockTime() == block.timestamp);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance >= balanceBefore + amount);
            } else {
                assert(address(c).balance == balanceBefore + amount);
            }
        } else {
            assert(c.pastBlockTime() < block.timestamp);
            assert(address(c).balance == balanceBefore);
        }
    }

    receive() external payable {}
}

