contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint ts) public payable {
        require(amount >= 1 ether, "must provide some value");
        require(address(this).balance >= amount, "insufficient balance");
        require(ts > c.pastBlockTime(), "timestamp must increase");

        uint balBefore = address(c).balance;
        uint pastBefore = c.pastBlockTime();
        uint selfBefore = address(this).balance;

        bool sent;
        try c.fallback{value: amount}() {
            sent = true;
        } catch {
            sent = false;
        }

        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;
        uint selfAfter = address(this).balance;

        if (sent && amount == 10 ether) {
            if (block.number % 15 == 0) {
                assert(balAfter == 0);
                assert(pastAfter == block.timestamp);
                assert(selfAfter == selfBefore + amount - balBefore);
            } else {
                assert(balAfter == balBefore + amount);
                assert(pastAfter == block.timestamp);
                assert(selfAfter == selfBefore - amount);
            }
        } else {
            assert(pastAfter == pastBefore);
            assert(balAfter == balBefore);
            assert(selfAfter == selfBefore);
        }
    }

    receive() external payable {}
}

