contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint advance) public payable {
        require(advance > 0, "advance must be positive");

        uint firstValue = uint(keccak256(abi.encodePacked(block.timestamp, address(this), advance, uint(1))));
        require(firstValue == 10 ether, "first value must be 10 ether");

        bool firstReverted;
        try c.call{value: firstValue}(bytes("")) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        require(!firstReverted, "setup call reverted");

        uint savedPastBlockTime = c.pastBlockTime();
        require(savedPastBlockTime != 0, "pastBlockTime should be set by setup call");

        uint targetTimestamp = savedPastBlockTime + advance;
        require(targetTimestamp != 0, "targetTimestamp must be nonzero");

        vm.warp(targetTimestamp);

        uint cBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        bool reverted;
        try c.call{value: 10 ether}(bytes("")) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (block.number % 15 == 0) {
            assert(!reverted);
            assert(address(c).balance == 0);
            assert(address(this).balance == testBalanceBefore + cBalanceBefore);
            assert(c.pastBlockTime() == targetTimestamp);
        } else {
            assert(!reverted);
            assert(address(c).balance == cBalanceBefore + 10 ether);
            assert(address(this).balance == testBalanceBefore - 10 ether);
            assert(c.pastBlockTime() == targetTimestamp);
        }
    }

    receive() external payable {}

    function vmWarp(uint) internal {}
}

